    int tx = threadIdx.x, ty = threadIdx.y;

    int row = by * blockDim.y + ty;
    int col = bx * blockDim.x + tx;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + 15) / 16; ++tile) {
        // Load tile of A into shared memory
        int a_col = tile * 16 + tx;
        if (row < N && a_col < N) {
            sA[ty][tx] = A[row * N + a_col];
        } else {
            sA[ty][tx] = 0.0f;
