    int row0 = by * 16 + ty * 2;
    int row1 = row0 + 1;
    int col0 = bx * 16 + tx * 2;
    int col1 = col0 + 1;

    float sum00 = 0.0f, sum01 = 0.0f;
    float sum10 = 0.0f, sum11 = 0.0f;

    for (int tile = 0; tile < (N + 15) / 16; ++tile) {
        // Load tile of A into shared memory
